export type AccountType = 'broker' | 'bank' | 'crypto' | 'cash' | 'deposit' | 'savings' | 'other'
export type AssetType =
  | 'stock'
  | 'bond'
  | 'etf'
  | 'currency'
  | 'cash'
  | 'deposit'
  | 'crypto'
  | 'real_estate'
  | 'vehicle'
  | 'other_physical'
  | 'other'

/** Asset types that do not have a market ticker. Ticker is auto-generated by backend. */
export const PHYSICAL_ASSET_TYPES = new Set<AssetType>([
  'real_estate', 'vehicle', 'other_physical', 'other',
])
export type OperationType =
  | 'buy'
  | 'sell'
  | 'deposit'
  | 'withdraw'
  | 'dividend'
  | 'coupon'
  | 'fee'
  | 'tax'
  | 'manual_valuation'
  | 'expense'
  | 'transfer'

export type ExpenseGroup = 'living' | 'investment' | 'credit'
export type OperationStatus = 'pending' | 'confirmed' | 'cancelled' | 'rejected'

export interface Account {
  id: string
  name: string
  account_type: AccountType
  currency: string
  created_at: string
}

export interface Asset {
  id: string
  ticker: string
  name: string
  asset_type: AssetType
  currency: string
  // Extended fields (migration h8i9j0k1l2m3)
  estimated_value: string | null
  note: string | null
  acquisition_date: string | null
  is_credit_linked: boolean
  credit_kind: string | null
  credit_note: string | null
  include_in_capital: boolean
}

/** Pick default account for income/expense/credit forms.
 *  Preference order: cash > bank > first account */
export function preferCashBankAccount(accounts: Account[]): string {
  const cash = accounts.find(a => a.account_type === 'cash')
  if (cash) return cash.id
  const bank = accounts.find(a => a.account_type === 'bank')
  if (bank) return bank.id
  return accounts[0]?.id ?? ''
}

