export const INCOME_SOURCES: { value: string; label: string }[] = [
  { value: 'salary',   label: 'Зарплата' },
  { value: 'advance',  label: 'Аванс' },
  { value: 'bonus',    label: 'Премия' },
  { value: 'gift',     label: 'Подарок' },
  { value: 'side_job', label: 'Подработка' },
  { value: 'freelance',label: 'Фриланс' },
  { value: 'business', label: 'Бизнес' },
  { value: 'cashback', label: 'Кэшбэк' },
  { value: 'refund',   label: 'Возврат' },
  { value: 'interest', label: 'Проценты' },
  { value: 'sale',     label: 'Продажа имущества вне учёта' },
  { value: 'other',    label: 'Другое' },
]

export function incomeSourceLabel(source: string | null): string {
  if (!source) return '—'
  return INCOME_SOURCES.find((s) => s.value === source)?.label ?? source
}

